Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
(* [comment removed for export] *)
Ltac lia ::= first [ zify_prune_sub; Zify.zify; xlia zchecker
                   | zify_prune; first [ zify_noeuclid; Z.euclidean_division_equations_cleanup; xlia zchecker | Zify.zify; xlia zchecker ]
                   | Zify.zify; xlia zchecker ].
Ltac tlia ::= sf_clear_big;
              first [ zify_prune_sub; Zify.zify; xlia zchecker
                    | Zify.zify; xlia zchecker
                    | sf_unhide;
                      first [ unpark_all; zify_prune_sub; Zify.zify; xlia zchecker
                            | zify_prune_neg; Zify.zify; xlia zchecker
                            | zify_prune_plain; Zify.zify; xlia zchecker
                            | Zify.zify; xlia zchecker ] ].

(* [comment removed for export] *)
Local Ltac in_live_tac ::=
  repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H end;
  repeat first [ eassumption | left; reflexivity
               | apply pm_copy_live_pix | apply pm_copy_live_data | apply pm_copy_live_cmap; solve [assumption]
               | apply pm_copy_live_sub; solve [eassumption]
               | apply in_or_app; right; right; right
               | right ].
Local Ltac live_sub_tac ::=
  let e := fresh "e" in let He := fresh "He" in intros e He;
  try solve [destruct He];
  first [ match goal with S : forall x, In x ?l -> In x ?l' |- In _ ?l' => lazymatch type of He with In _ l => exact (S _ He) end end
        | repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H in * end;
          repeat first [ exact He
                       | match goal with S : forall x, In x ?l -> In x ?l' |- In _ ?l' => lazymatch type of He with In _ l => exact (S _ He) end end
                       | apply pm_copy_live_sub; exact He
                       | apply in_or_app; right; right; right; exact He
                       | right ] ].
Ltac show_pc := lazymatch goal with
  | |- cps _ (ASTA _ _ _ (eq (MS _ _ ?pc _ _ _ _))) _ => idtac "CPS-MS pc=" pc
  | |- cps _ (ASTA _ _ _ (eq ?st)) _ => idtac "CPS other"
  | |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "EVT pc=" pc
  | |- ?g => idtac "OTHER" end.


(* [comment removed for export] *)
Definition csc_sc : Z := e_pixCloseSafeCompBrick + 0x190.

(* [comment removed for export] *)
Ltac keeps_munch RT AF Sg fr usp L K :=
  lazymatch goal with MUx : munch _ ?ma ?mb |- _ => lazymatch goal with Ax : ART RT ?S4 ma |- _ =>
    let FRS4 := fresh "FRS4" in
    assert (FRS4 : rt_frames RT S4 = (fr, 2%nat) :: rt_frames RT Sg) by (repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; reflexivity);
    assert (K : keeps_live L ma mb)
      by (let bb := fresh "bb" in let kk := fresh "kk" in let Hin := fresh "Hin" in let aa := fresh "aa" in let Haa := fresh "Haa" in let Hin4 := fresh "Hin4" in
          intros bb kk Hin aa Haa; apply MUx;
          assert (Hin4 : In (bb, kk) (rt_live RT S4))
            by (first [exact Hin | revert Hin; repeat match goal with H : rt_live RT _ = rt_live RT _ |- _ => rewrite H end; first [exact (fun h => h) | live_sub_tac]]);
          let LR0 := fresh "LR0" in let LR1 := fresh "LR1" in let LR2 := fresh "LR2" in let D1 := fresh "D1" in let D2 := fresh "D2" in
          pose proof (af_live_range RT AF S4 ma bb kk Ax Hin4) as (LR0 & LR1 & LR2);
          pose proof (af_frames_range RT AF S4 ma fr 2%nat Ax ltac:(rewrite FRS4; left; reflexivity)) as (_ & _ & _ & D1); specialize (D1 bb kk Hin4);
          pose proof (af_fshadow_apart RT AF S4 ma fr 2%nat Ax ltac:(rewrite FRS4; left; reflexivity)) as (D2 & _); specialize (D2 bb kk Hin4);
          change (fs_size 2%nat) with 256 in D1, D2; unfold shad, SHB in D2;
          repeat match goal with H : rt_sp0 RT _ = _ |- _ => rewrite H in LR1 end; unfold STACK_WIN, USTACK_TOP, RT_STACK, SEGTOP_A in LR1, LR2;
          cbn [outside]; repeat match goal with H : rt_sp0 RT Sg - _ <= _ |- _ => revert H end; repeat match goal with H : _ + (65536 + _) <= usp |- _ => revert H end;
          clear - LR0 LR1 LR2 D1 D2 Haa; intros; repeat split; try exact I; first [lia | Z.div_mod_to_equations; lia]);
    clear FRS4 end end.

(* [comment removed for export] *)
Ltac keeps_callF RT AF Sg fr L K :=
  lazymatch goal with AGx : agree_on (fun a => aclient (rt_live RT ?S5) ?frs ?spx a /\ outside ?W a) ?m1 ?m2 |- _ =>
  lazymatch goal with Ax : ART RT ?S4 m1 |- _ =>
    let FRS4 := fresh "FRS4" in
    assert (FRS4 : rt_frames RT S4 = (fr, 2%nat) :: rt_frames RT Sg) by (repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; reflexivity);
    assert (K : keeps_live L m1 m2)
      by (apply (keeps_live_of_agree _ _ _ _ m1 m2 _ AGx);
          [ solve [live_sub_tac]
          | let bb := fresh "bb" in let kk := fresh "kk" in let xx := fresh "xx" in let Hin := fresh "Hin" in let Hxx := fresh "Hxx" in let D1 := fresh "D1" in
            let Hin4 := fresh "Hin4" in
            intros bb kk xx Hin Hxx;
            assert (Hin4 : In (bb, kk) (rt_live RT S4))
              by (first [exact Hin | revert Hin; repeat match goal with H : rt_live RT _ = _ |- _ => rewrite H end; first [exact (fun h => h) | live_sub_tac]]);
            pose proof (af_frames_range RT AF S4 m1 fr 2%nat Ax ltac:(rewrite FRS4; left; reflexivity)) as (_ & _ & _ & D1);
            specialize (D1 bb kk Hin4); change (fs_size 2%nat) with 256 in D1;
            cbn [outside]; clear - D1 Hxx; repeat split; try exact I; lia ]);
    clear FRS4 end end.

(* [comment removed for export] *)
Ltac keeps_callH RT AF L hd K :=
  lazymatch goal with AGx : agree_on (fun a => aclient (rt_live RT ?S5) ?frs ?spx a /\ outside ?W a) ?m1 ?m2 |- _ =>
  lazymatch goal with Ax : ART RT S5 m1 |- _ =>
    assert (K : keeps_live L m1 m2);
    [ apply (keeps_live_of_agree _ _ _ _ m1 m2 _ AGx);
      [ | let bb := fresh "bb" in let kk := fresh "kk" in let xx := fresh "xx" in let Hin := fresh "Hin" in let Hxx := fresh "Hxx" in let AP := fresh "AP" in
          intros bb kk xx Hin Hxx;
          assert (AP : bb + kk <= hd \/ hd + 64 <= bb); [ apply (live_apart2 RT AF S5 m1 bb kk hd 64 Ax) | cbn [outside]; clear - AP Hxx; repeat split; try exact I; lia ] ]
    | ] end end.

Ltac livn := repeat match goal with H : rt_live _ _ = rt_live _ _ |- _ => rewrite H end.

(* [comment removed for export] *)
Ltac split_rows H := lazymatch type of H with
  | Forall _ (_ :: _) => let T := fresh "TR" in pose proof (Forall_inv H) as T; cbn [fst snd po_row app] in T;
                        let H2 := fresh "RW" in pose proof (Forall_inv_tail H) as H2; clear H; split_rows H2
  | _ => clear H end.

(* [comment removed for export] *)
Ltac mk_ucx m usp bsp s0 us0 ura ras UCTX ES0 ERA SPA SPT UCX :=
  let RA4096 := fresh "RA4096" in
  assert (RA4096 : 4096 <= ura < 2^64) by (first [assumption | split; assumption]);
  lazymatch goal with AG : agree_on ?PFx m ?mc, FRx : rw_cells asegs ?mc bsp _ |- _ =>
    let UCTXc := fresh "UCTXc" in let FRc := fresh "FRc" in let REC := fresh "REC" in
    assert (UCTXc : chain_ok mc usp us0 ras)
      by (apply (chain_ok_keep ras m mc usp us0 UCTX); eapply agree_sub; [exact AG|]; cbv beta; intros zz Hzz; left; exact Hzz);
    pose proof FRx as FRc; split_before FRc (C8 s0) REC; clear FRc; rewrite ES0, ERA in REC;
    assert (UCX : chain_ok mc bsp usp (ura :: ras))
      by (apply (chain_ok_push mc bsp usp ura us0 ras);
          [clear; lia| clear - SPA; Z.div_mod_to_equations; lia| unfold USTACK_TOP; clear - SPT; lia| exact RA4096
          | unfold us0; apply bv_unsigned_in_range| exact REC| exact UCTXc]);
    clear REC UCTXc RA4096 end.

(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac after_call_open RT :=
  cps_open RT; after_call_unfold; fold_zdefs; unfold rt_after, rt_after_f in *; split_hyps; unfold SEGTOP_A, STACK_WIN, USTACK_TOP, RT_STACK in *;
  repeat match goal with H : context [bv_unsigned (Z_to_bv 64 ?e)] |- _ => rewrite (unsigned_lit e) in H by lia end;
  lazymatch goal with
  | P : rt_pres ?lv ?frs ?spc ?ma ?mb |- _ =>
      let AG := fresh "AG" in assert (AG : agree_on (aclient lv frs spc) ma mb) by (intros ? Ha; exact (P _ Ha)); clear P
  | P : rt_pres_fp ?lv ?frs ?spc ?W ?ma ?mb |- _ =>
      let AG := fresh "AG" in assert (AG : agree_on (fun a => aclient lv frs spc a /\ outside W a) ma mb) by (intros ? [Ha Hb]; exact (P _ Ha Hb)); clear P
  end; fix_ret_pc.
Ltac tr_cell AG H side :=
  lazymatch type of AG with agree_on _ ?ma ?mb =>
    lazymatch type of H with rw_cells _ _ ?A ?cs =>
      apply (rw_cells_agree_nw asegs ma mb A cs) in H;
      [| let a := fresh "a" in let Ha := fresh "Ha" in intros a Ha; cbn [cells_size csize Nat.add length Z.of_nat Pos.of_succ_nat Pos.succ] in Ha; apply AG; side Ha ] end end.
Ltac drop_old ma := repeat match goal with
  | H : acc asegs ma _ _ |- _ => clear H | H : mem_inv asegs ma |- _ => clear H | H : stk asegs ma _ _ |- _ => clear H
  | H : munch _ _ ma |- _ => clear H | H : wmono asegs _ ma |- _ => clear H | H : LIBH ma |- _ => clear H | H : io_ssp ma |- _ => clear H
  | H : rw_cells asegs ma _ _ |- _ => fail 100 "leftover cell (add a tr_cell case):" H | H : ro_cells asegs ma _ _ |- _ => clear H | H : bytes_at asegs ma _ _ |- _ => clear H end.
(* [comment removed for export] *)
Ltac tr_cells_fp AG FRS fr usp :=
  lazymatch type of AG with agree_on _ ?ma ?mb =>
    repeat match goal with H : rw_cells asegs ma (fr + ?o) _ |- _ =>
      tr_cell AG H ltac:(fun Ha => split; [ right; right; right; left; exists fr, 2%nat; split; [rewrite FRS; left; reflexivity| change (fs_size 2%nat) with 256; clear - Ha; lia]
                                          | cbn [outside]; clear - Ha; repeat split; try exact I; lia ]) end;
    repeat match goal with H : rw_cells asegs ma fr _ |- _ =>
      tr_cell AG H ltac:(fun Ha => split; [ right; right; right; left; exists fr, 2%nat; split; [rewrite FRS; left; reflexivity| change (fs_size 2%nat) with 256; clear - Ha; lia]
                                          | cbn [outside]; clear - Ha; repeat split; try exact I; lia ]) end;
    repeat match goal with H : rw_cells asegs ma (fr / 8 + _) _, FRSH' : parked (fr + 256 <= ?K \/ ?K2 <= fr), FR64' : fr mod 64 = 0 |- _ =>
      tr_cell AG H ltac:(fun Ha => split; [ right; right; right; right; exists fr, 2%nat; split; [rewrite FRS; left; reflexivity| unfold shad, SHB; change (fs_size 2%nat) with 256; clear - Ha FR64'; Z.div_mod_to_equations; lia]
                                          | cbn [outside]; unfold shad, SHB in *; generalize FRSH'; unfold parked at 1; clear - Ha; intro; repeat split; try exact I; lia ]) end;
    repeat match goal with H : rw_cells asegs ma (usp + ?o) _, SPT' : usp + 16 <= _, FRHI' : fr + 256 <= _ - _, LOW' : _ - _ <= ?lo', LOR' : ?lo' + _ <= usp |- _ =>
      tr_cell AG H ltac:(fun Ha => split; [ left; unfold USTACK_TOP; clear - Ha SPT'; lia | cbn [outside]; clear - Ha FRHI' LOW' LOR'; repeat split; try exact I; lia ]) end
  end.

Ltac at_pc := lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 ?p) _ _ _ _) => idtac "AT" p | |- evt _ _ (MS _ _ ?p _ _ _ _) => idtac "AT-IF" p
                                  | |- cps _ (ASTA _ _ _ (eq (MS _ _ (Z_to_bv 64 ?p) _ _ _ _))) _ => idtac "CPS-AT" p | |- ?g => idtac "STUCK-AT:" g end.

Section CSC_R.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis DILN : pixDilate_null0_cps RT.        (* [comment removed for export] *)
Hypothesis ERON : pixErode_null0_cps RT.         (* [comment removed for export] *)
Hypothesis PDN : pixDestroy_null_cpsF RT.        (* [comment removed for export] *)
Hypothesis REMBN : pixRemoveBorder_null_cps RT.  (* [comment removed for export] *)
Hypothesis CPYN : pixCopy_srcnull_cps RT.        (* [comment removed for export] *)
Hypothesis SELD : selDestroy_cps RT.             (* [comment removed for export] *)
Variables (Σ : rts RT) (PMc : Model -> Prop) (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 gp : word) (F : bvmap 5 word)
          (usp lo : Z) (m : mem) (pix1 hs vs : Z) (v : pixv) (cv : cmapv) (ras : list Z).
Hypothesis CTX : csc_ctx RT Σ PMc ra s0 usp lo m pix1 hs vs v cv ras.

Theorem csc_r30_0 :
  csc_cutR_0 RT Σ PMc ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 gp F usp lo m pix1 hs vs v cv true
             (csc_Q RT Σ PMc ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 gp F usp lo m pix1 v cv).
Proof using AF GP FKC DILN ERON PDN REMBN CPYN SELD CTX.
